class EmailValidator:
    def __init__(self):
        self.local_re = self._build_local_re()
        self.domain_re = self._build_domain_re()

    def _build_local_re(self):
        # allowed chars in the local part
        return '[A-Za-z0-9!#$%&\'*+/=?^_`{|}~.-]+'

    def _build_domain_re(self):
        return '[A-Za-z0-9](?:[A-Za-z0-9-]{0,61}[A-Za-z0-9])?'

    def _split(self, value):
        if value.count('@') != 1:
            return None, None
        return value.split('@')

    def _check_local(self, local):
        import re
        return bool(re.fullmatch(self.local_re, local))

    def _check_domain(self, domain):
        import re
        labels = domain.split('.')
        if len(labels) < 2:
            return False
        return all(re.fullmatch(self.domain_re, lbl) for lbl in labels)

    def validate(self, value):
        local, domain = self._split(value)
        if local is None:
            return False
        return self._check_local(local) and self._check_domain(domain)


def is_valid_email(value):
    return EmailValidator().validate(value)
